389: function createLife() {
390:   const value = selector => $(selector)?.value?.trim() || ''; const name = value('#newName').slice(0, 28) || 'Alex'; const city = value('#newCity').slice(0, 28) || 'São Paulo';
391:   const previous = state;
392:   const liquidLegacy = Math.max(0, safeNumber(previous.money) + safeNumber(previous.finances?.investments) - safeNumber(previous.finances?.debt));
393:   const inheritance = previous.dead ? Math.round(liquidLegacy * .15) : 0;
