293: function advanceYear() {
294:   if (state.dead) return toast('Esta vida chegou ao fim. Comece uma nova história.');
295:   state.age++; state.year++; const c = state.career;
296:   const wasInPrison = state.prisonYears > 0;
297:   if (wasInPrison) state.prisonYears = Math.max(0, state.prisonYears - 1);
298:   const income = c.employed && state.prisonYears === 0 && !wasInPrison ? c.salary * 12 : 0;
299:   const expenses = Math.round(state.finances.expenses * 12 * (1 + state.age / 500));
300:   const investmentReturn = state.finances.investments * ((Math.random() * .12) - .03);
301:   state.finances.investments = Math.max(0, state.finances.investments + investmentReturn);
302:   const balanceBeforeDebt = state.money + income - expenses;
303:   const deficit = Math.max(0, -balanceBeforeDebt);
304:   state.money = Math.max(0, balanceBeforeDebt);
305:   if (deficit) { state.finances.debt += deficit; state.credit = clamp(state.credit - 35, 0, 900); }
306:   else { state.finances.debt = Math.max(0, state.finances.debt - Math.min(state.finances.debt, income * .05)); state.credit = clamp(state.credit + 8, 0, 900); }
307:   const agePenalty = state.age > 70 ? 2.5 : state.age > 45 ? 1 : .25;
308:   state.health = clamp(state.health - agePenalty - (state.stress > 70 ? 1.5 : 0));
309:   changeStat('happiness', deficit ? -6 : state.money > expenses ? 1 : -1);
310:   state.stress = clamp(state.stress + 3 + (deficit ? 5 : 0) - (state.trait === 'espiritual' ? 2 : 0));
311:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
312:   state.relationships.forEach(person => { person.affinity = clamp(person.affinity - (Math.random() < .4 ? 2 : 0)); });
313:   state.children.forEach(child => { child.age = safeNumber(child.age) + 1; });
314:   if (c.employed) {
315:     c.skill = clamp(c.skill + (state.education > 70 ? 4 : 2));
316:     c.satisfaction = clamp((c.satisfaction || 70) + (c.remote ? 1 : -1) - (state.stress > 70 ? 3 : 0));
317:     if (Math.random() < .3 && c.level < 10) { c.level++; c.salary = Math.round(c.salary * 1.08); addEvent('↗', 'Uma promoção chegou', `Seu salário agora é ${money(c.salary)} por mês.`, 'blue'); }
318:   }
319:   if (state.age >= 45 && Math.random() < .08 && !state.healthConditions.includes('pressão alta')) state.healthConditions.push('pressão alta');
320:   const event = yearlyEvent(); addEvent(event.icon, event.title, event.text, event.cls);
321:   if (wasInPrison) addEvent('⚖', 'Um ano difícil', state.prisonYears ? `Você cumpriu mais um ano de prisão. Restam ${state.prisonYears}.` : 'Você cumpriu sua pena e está tentando reconstruir a vida.', 'pink');
322:   state.history.push({ year: state.year, age: state.age, money: Math.round(state.money), career: c.title });
323:   const reachedLimit = state.age >= 105;
324:   const healthFailure = state.health <= 0;
325:   const lateLifeRisk = state.age >= 92 && Math.random() < .15;
326:   if (healthFailure || lateLifeRisk || reachedLimit) {
327:     state.dead = true;
328:     state.deathCause = healthFailure ? 'complicações de saúde' : reachedLimit ? 'idade avançada' : 'fim natural da jornada';
329:     addEvent('☾', 'O fim de uma jornada', `Sua história terminou por ${state.deathCause}, mas seu legado permanece.`, 'pink');
330:   }
331:   commit(`Ano ${state.year}: ${income >= expenses ? 'suas contas fecharam no azul' : 'suas despesas exigiram atenção'}`);
332: }
